import CN_common from"./common.js";export default{fetch:async function(path,params,options){let url=`${ROOT_URL}/api/${path}`;if(CN_common.is_object(params)){if(params.select)params.select=this.select(params.select);if(params.modifier)params.modifier=this.modifier(params.modifier);const url_search_params=new URLSearchParams(params);url+=`?${url_search_params.toString()}`}else if(CN_common.is_string(params)){url+=`?${params}`}const response=await fetch(url,options);if(300<=response.status){const body=await response.text();let error=new URIError;error.error_code=null;error.response=response;error.body=body;if(306==response.status&&body){error.name="Please Note";error.message=JSON.parse(body)}else{let message=null;if(403==response.status){error.name="Permission Denied";message="you do not have access to the requested resource."}else if(404==response.status){error.name="Not Found";message="because the needed resource could not be found."}else if(406==response.status){error.name="Format Unavailable";message="because the requested format is not available."}else if(409==response.status){error.name="Conflict";message="due to a pre-existing conflict."}else{error.name="Server Error";message="due to a server-based error.";if(body)error.error_code=JSON.parse(body)}if(message){error.message=error.message?`${error.message} ${message}`:CN_common.uc_first(message)}if(response.status)error.name+=` (${response.status})`}throw error}return response},get:async function(path,params){return await this.fetch(path,params)},patch:async function(path,data){return await this.fetch(path,null,{method:"PATCH",body:JSON.stringify(data),headers:{"Content-type":"application/json"}})},post:async function(path,data){return await this.fetch(path,null,{method:"POST",body:JSON.stringify(data),headers:{"Content-type":"application/json"}})},delete:async function(path){return await this.fetch(path,null,{method:"DELETE"})},select:function(select){return JSON.stringify(this.shorten_select(select))},shorten_select:function(select){if(Array.isArray(select)){return select.map(item=>this.shorten_select(item))}else if(CN_common.is_object(select)){let new_select={};for(var key in select){if(Object.prototype.hasOwnProperty.call(select,key)){const value=this.shorten_select(select[key]);if("alias"==key)key="a";else if("column"==key)key="c";else if("distinct"==key)key="d";else if("from"==key)key="f";else if("table_prefix"==key)key="p";else if("table"==key)key="t";new_select[key]=value}}return new_select}return select},modifier:function(modifier){return JSON.stringify(this.shorten_modifier(modifier))},shorten_modifier:function(modifier){if(Array.isArray(modifier)){return modifier.map(item=>this.shorten_modifier(item))}else if(CN_common.is_object(modifier)){let new_modifier={};for(var key in modifier){if(Object.prototype.hasOwnProperty.call(modifier,key)){const value=this.shorten_modifier(modifier[key]);if("alias"==key)key="a";else if("bracket"==key)key="b";else if("column"==key)key="c";else if("having"==key)key="h";else if("join"==key)key="j";else if("limit"==key)key="l";else if("open"==key)key="n";else if("order"==key)key="o";else if("offset"==key)key="off";else if("onleft"==key)key="onl";else if("operator"==key)key="op";else if("onright"==key)key="onr";else if("prepend"==key)key="p";else if("table"==key)key="t";else if("type"==key)key="tp";else if("value"==key)key="v";else if("where"==key)key="w";new_modifier[key]=value}}return new_modifier}return modifier}};
